import JobSidebar from "@/components/JobSidebar";
import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";

/**
 * Shared layout with persistent JobSidebar + AppHeader.
 * Used by all authenticated pages (Settings, Billing, Admin, etc.).
 */
const SidebarLayout = ({ children }: { children: React.ReactNode }) => {
  const { user } = useAuth();
  const navigate = useNavigate();

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        showDashboard={false}
        showMyJobs={false}
        onNewJob={() => navigate("/?new=1")}
        onDashboard={() => navigate("/")}
        onMyJobs={() => navigate("/jobs")}
        onAuthRequired={() => navigate("/auth")}
        isAuthenticated={!!user}
      />
      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
          <AppHeader />
          <div className="flex items-center h-10 px-4 md:hidden">
            <SidebarTrigger />
          </div>
          <div className="flex-1 overflow-y-auto">
            {children}
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
};

export default SidebarLayout;
